package com.iptvplayer.app.i18n

import androidx.compose.runtime.Composable
import androidx.compose.runtime.compositionLocalOf
import java.util.Locale

/**
 * Lekki system tłumaczeń appki — celowo NIE korzysta z Android strings.xml, bo ten
 * wymagałby zmiany konfiguracji CAŁEJ Activity (locale systemowe), żeby przełączyć
 * język w locie. Tutaj: zwykła mapa klucz -> tłumaczenie per język, czytana przez
 * CompositionLocal `LocalLang`, więc zmiana języka w Ustawieniach odświeża od razu
 * CAŁY UI, bez restartu appki i bez rekonfiguracji Activity.
 *
 * Użycie w @Composable: `tr("home.clock.never")`.
 * Z wartościami: `tr("home.status.summary", playlistCount, channelCount)` — WAŻNE:
 * placeholdery w tabeli są pozycyjne (%1\$s, %2$d…), NIE %s/%s po kolei, bo kolejność
 * słów bywa inna w różnych językach (np. rosyjski/niemiecki potrafią odwracać kolejność
 * względem polskiego).
 *
 * Poza drzewem Compose (np. Toasty wywoływane wprost z MainActivity, poza setContent)
 * używamy `trFor(lang, key, …)` — tej samej tabeli, ale z jawnie podanym językiem
 * (odczytanym np. z `viewModel.state.value.language`), bo tam LocalLang nie jest dostępny.
 */

/** Aktualny język appki (kod ISO, patrz SUPPORTED_LANGUAGES) — dostarczany przez
 * CompositionLocalProvider w MainActivity.setContent, ponad całym drzewem UI. */
val LocalLang = compositionLocalOf { "pl" }

/** Języki wspierane przez appkę (wybór w Ustawieniach) — jedno źródło prawdy, żeby
 * SettingsScreen i reszta appki zawsze się zgadzały co do dostępnych kodów. Nazwy
 * CELOWO nie są tłumaczone — język pokazuje się zawsze pod własną, natywną nazwą
 * (tak jak w prawie każdej appce), niezależnie od aktualnie wybranego języka UI. */
val SUPPORTED_LANGUAGES = listOf(
    "pl" to "Polski",
    "en" to "English",
    "de" to "Deutsch",
    "ru" to "Русский",
    "uk" to "Українська",
    "es" to "Español",
    "fr" to "Français",
)

@Composable
fun tr(key: String, vararg args: Any): String = trFor(LocalLang.current, key, *args)

/** Wersja bez kontekstu Compose — do użycia w Toastach/logice poza drzewem UI (np.
 * MainActivity poza setContent). Wymaga jawnego podania aktualnego języka appki. */
fun trFor(lang: String, key: String, vararg args: Any): String {
    val row = Strings.table[key] ?: return key
    val template = row[lang] ?: row["pl"] ?: row["en"] ?: key
    if (args.isEmpty()) return template
    return try {
        String.format(Locale(lang), template, *args)
    } catch (e: Exception) {
        template
    }
}

